?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Games Club BD</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"><link href="https://fonts.googleapis.com/css2?family=Lato:wght@300;400;700;900&family=Hind+Siliguri:wght@300;400;500;600;700&display=swap" rel="stylesheet"><style>:root{--primary:#1976d2;--secondary:#ff9800;--bg:#f5f6fa}*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Lato,'Hind Siliguri',sans-serif;color:#222;padding-bottom:76px}.top{background:linear-gradient(135deg,#1976d2,#42a5f5);color:white;padding:28px 20px 34px;border-radius:0 0 20px 20px}.top h1{font-size:24px;margin:0 0 8px}.top p{margin:0}.wrap{max-width:620px;margin:18px auto;padding:0 15px}.card{background:white;border-radius:14px;padding:20px;margin:14px 0;box-shadow:0 4px 15px #0000000a}.section-title{font-size:18px;font-weight:900;margin:0 0 14px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.tile{background:white;border-radius:12px;padding:20px 14px;text-decoration:none;color:#222;box-shadow:0 4px 15px #0000000a}.tile i{color:var(--primary);font-size:22px;margin-bottom:12px}.tile strong{display:block}.btn{display:block;width:100%;border:0;background:var(--primary);color:white;padding:13px;border-radius:8px;font-size:15px;font-weight:800;text-decoration:none;text-align:center;cursor:pointer}.muted{color:#687080;font-size:14px}.wallet{display:flex;justify-content:space-between;align-items:center}.balance{font-size:22px;font-weight:900;color:#111}.tabs{position:fixed;bottom:0;left:0;right:0;height:65px;background:white;display:flex;justify-content:space-around;align-items:center;box-shadow:0 -2px 10px #00000010}.tabs a{text-align:center;text-decoration:none;color:#111;font-size:12px}.tabs i{display:block;color:#1976d2;margin-bottom:4px}.msg{padding:12px;border-radius:8px;background:#fff3cd;color:#664d03;margin-bottom:14px}input{width:100%;padding:12px;border:1px solid #ddd;border-radius:7px;margin:5px 0 12px;font:inherit}.row{display:flex;gap:10px}.row>*{flex:1}@media(min-width:650px){.hero-grid{grid-template-columns:repeat(3,1fr)}}</style></head><body><header class="top"><h1><i class="fa-solid fa-gamepad"></i> Games Club BD</h1><p>Join matches and win big prizes.</p></header><main class="wrap"><?php if ($notice): ?><div class="msg"><?= h($notice) ?></div><?php endif; ?><section class="card wallet"><div><div class="muted">DEPOSIT BALANCE</div><div class="balance">৳ <?= $user ? number_format((float)$user['deposit_balance'], 2) : '0.00' ?></div></div><a class="btn" style="width:auto;padding:10px 18px" href="add-money.php">ADD MONEY</a></section><?php if ($user): ?><section class="card"><h2 class="section-title">Welcome, <?= h($user['name']) ?></h2><p class="muted"><?= h($user['email']) ?></p><form method="post" action="logout.php"><input type="hidden" name="csrf_token" value="<?= h($csrf) ?>"><button class="btn" type="submit" style="background:#687080">Log out</button></form></section><?php else: ?><section class="card"><h2 class="section-title">Login / Register</h2><div class="row"><div><label class="muted" for="auth-name">Full Name (registration)</label><input id="auth-name" autocomplete="name" placeholder="Your name"></div><div><label class="muted" for="auth-email">Email</label><input id="auth-email" type="email" autocomplete="email" placeholder="name@example.com"></div></div><label class="muted" for="auth-password">Password (at least 8 characters to register)</label><input id="auth-password" type="password" autocomplete="current-password" placeholder="Password"><div class="row"><button id="login-button" class="btn" type="button">Login</button><button id="register-button" class="btn" type="button" style="background:#4caf50">Register</button></div><p id="auth-result" class="muted" role="status"></p></section><?php endif; ?><h2 class="section-title" style="margin:22px 4px 12px">Explore Games</h2><section class="grid hero-grid"><a href="add-money.php" class="tile"><i class="fa-solid fa-wallet"></i><strong>My Wallet</strong><span class="muted">Manage your balance</span></a><a href="#matches" class="tile"><i class="fa-solid fa-trophy"></i><strong>Matches</strong><span class="muted">Upcoming tournaments</span></a><a href="#results" class="tile"><i class="fa-solid fa-medal"></i><strong>Results</strong><span class="muted">Match results</span></a></section><section id="matches" class="card" style="margin-top:16px"><h2 class="section-title">FREE FIRE</h2><p class="muted">Welcome to Games Club BD Tour! Join matches and win big prizes.</p><p class="muted">Tournament listings will appear here as matches are added.</p></section></main><nav class="tabs"><a href="index.php"><i class="fa-solid fa-house"></i>Home</a><a href="#matches"><i class="fa-solid fa-trophy"></i>Matches</a><a href="#results"><i class="fa-solid fa-medal"></i>Result</a><a href="add-money.php"><i class="fa-solid fa-user"></i>Profile</a></nav><script>const csrf=<?= json_encode($csrf) ?>;async function auth(action){const out=document.getElementById('auth-result');out.textContent='Please wait…';try{const r=await fetch('api/auth.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({action,name:document.getElementById('auth-name').value,email:document.getElementById('auth-email').value,password:document.getElementById('auth-password').value})});const d=await r.json();if(!d.ok)throw new Error(d.error||'Request failed.');location.reload()}catch(e){out.textContent=e.message}}document.getElementById('login-button')?.addEventListener('click',()=>auth('login'));document.getElementById('register-button')?.addEventListener('click',()=>auth('register'));</script></body></html>
